/* * 拼好码.css - 二次创作版（感谢墨千尾老师的拼好码模板和宝宝教程，感谢na老师和nini老师的代码）
* 修改：Gemini (Based on user request)
*/

/*字体*/
@import url("https://fontsapi.zeoseven.com/3/main/result.css");

body {
    font-family: "寒蝉全圆体";
    font-weight: normal;
}


/* ===一、全局控制===（在这里改想改的变量） */
:root {
  /* * 更新字体变量：这里我们将 寒蝉全圆体 设为首选 
   * 加上 sans-serif 是为了防止字体加载失败时有备用方案
   */
  --字体1: "寒蝉全圆体", sans-serif; 

  /* 自定义文案 */
  --自定义思维链文案: "正在动脑筋...";
  --自定义“加载更多信息”文案: "再翻翻看...";
  --自定义输入框文字: "说点什么...";

  /* * 核心配色变量 (Chiikawa Palette) */
  --chiikawa-pink: rgba(255, 226, 226, 1); /* 吉伊粉 */
  --hachiware-blue: rgba(220, 243, 255, 1); /* 小八蓝 */
  --usagi-yellow: #fffcdb;  /* 乌萨奇黄 */
  --text-grey: #665a5a;     /* 柔和的深灰，不使用纯黑 */
  --usagi-pink: rgba(253, 177, 195, 1);  /* 兔兔耳朵色（勾选框） */
  --choco-text: #5e4a4a;   /* 焦糖可可 (深棕文字，清晰又温柔) */
  --chiikawa-pink2: rgba(245, 194, 222, 1); /* 吉伊深粉 (图标主色) */
  --hachi-blue: #89c2d9;    /* 小八深蓝 (边框颜色) */

  --背景图: url('https://i.postimg.cc/yNhYHXTT/1766723845247.jpg');  /*主题面板背景图*/
  --头像框: url('https://i.postimg.cc/c44dmc1Z/1766671735512.png');  /*头像框链接*/
}

/* 定义全局字体 */
body{
  font-family: var(--字体1); /* 调用上面定义的变量 */
  font-weight: normal;
  color: var(--text-grey); /* 全局文字颜色柔和化 */
}

/* 定义全局弹出面板主色调 (抽屉/设置面板) */
.drawer-content, #table_drawer_content, .options-content {
  background-color: rgba(255, 255, 255, 0.7) !important; /* 半透明奶白 */
  border-color: none !important;
  border-radius: 10px !important; /* 大圆角 */
  color: var(--text-grey) !important;
  font-family: var(--字体1) !important; /* 强制应用圆体 */
}

/* ===== 二、顶栏 (点击修复版) ===== */
#top-settings-holder {
    /* 1. 顶栏背景：半透明白底 */
    background-color: rgba(255, 255, 255, 0.9);
    backdrop-filter: blur(5px);

    /* 2. 关键设置：允许花边“溢出”显示 */
    overflow: visible !important;

    /* 3. 布局微调 */
    border: none;
    border-radius: 0 0 10px 10px;
    box-shadow: 0 2px 10px rgba(200, 200, 200, 0);

    /* 【重要】不要在这里加 z-index，让它保持默认层级，这样才不会挡住点击 */
    position: relative; 

    /* 给下面的聊天内容留出一点距离，防止花边挡住第一条消息 */
    margin-bottom: 40px; 
}

/* 清理父容器 */
#top-bar {
    background: transparent !important;
    border: none !important;
    overflow: visible !important;
    box-shadow: none;
}

/* --- 装饰花边 (挂在外面) --- */
#top-settings-holder::after {
    content: '';
    display: block;
    position: absolute;

    /* 1. 位置：挂在顶栏的最下面 */
    top: -50%; 
    left: 0;
    width: 100%;

    /* 2. 尺寸和素材 */
    height: 60px; /* 高度 */
    background-image: url('https://i.postimg.cc/DZWbXkpk/211947.png');
    background-repeat: repeat-x;
    background-size: auto 100%;
    background-position: top center;

    /* 3. 【核心修复】鼠标穿透 */
    /* 这行代码保证鼠标点在花边上时，会直接“穿过去”点到下面的东西，绝不拦路 */
    pointer-events: none !important; 

    /* 4. 视觉层级 */
    /* 只要比聊天气泡高一点点就行，不需要太高 */
    z-index: -1; 
}

/* --- 图标替换 (安全版) --- */
/* 这里不再动 z-index，只单纯替换图片 */
#top-settings-holder .drawer-icon::before {
  content: '' !important;
  display: inline-block;

  /* 尺寸 */
  width: 25px;  
  height: 25px; 
  background-size: contain; 
  background-repeat: no-repeat;
  background-position: center;

  transition: transform 0.3s ease-in-out;
}

/* 悬停效果 */
#top-settings-holder .drawer-icon:hover::before {
    transform: scale(1.2) rotate(15deg);
}

.drawer-icon.fa-sliders::before {
   background-image: url('https://i.postimg.cc/D0y0sKMT/205739.png') !important;
}

.drawer-icon.fa-plug::before {
   background-image: url('https://i.postimg.cc/j2d2NrFT/205808.png') !important;
}

.drawer-icon.fa-font::before {
   background-image: url('https://i.postimg.cc/VvLvMcVc/205834.png') !important;
}

.drawer-icon.fa-book-atlas::before {
   background-image: url('https://i.postimg.cc/D0y0sKMT/205739.png') !important;
}

.drawer-icon.fa-user-cog::before {
   background-image: url('https://i.postimg.cc/j2d2NrFT/205808.png') !important;
}/*旧版本设置按钮*/

.drawer-icon.fa-user::before {
   background-image: url('https://i.postimg.cc/j2d2NrFT/205808.png') !important;
}/*新版本设置按钮*/

.drawer-icon.fa-panorama::before {
   background-image: url('https://i.postimg.cc/VvLvMcVc/205834.png') !important;
}/*旧版本背景按钮*/

.drawer-icon.fa-image::before {
   background-image: url('https://i.postimg.cc/VvLvMcVc/205834.png') !important;
}/*新版本背景按钮*/

.drawer-icon.fa-cubes::before {
   background-image: url('https://i.postimg.cc/D0y0sKMT/205739.png') !important;
}

.drawer-icon.fa-face-smile::before {
   background-image: url('https://i.postimg.cc/j2d2NrFT/205808.png') !important;
}

.drawer-icon.fa-address-card::before {
   background-image: url('https://i.postimg.cc/VvLvMcVc/205834.png') !important;
}


/* ===== 三、底栏 (悬浮·最终修复版，感谢nakari老师的悬浮底栏代码) ===== */
/* 基于 Nakari老师的代码调整逻辑：外层透明，内层美化 */

/* 1. 【核心】让外层容器完全隐身 */
/* 这就是那个“白框”的真身，我们把它变透明 */
#send_form, body.no-blur #send_form, #form_sheld {
  background: transparent !important;
  background-color: transparent !important;
  border: none !important;
  backdrop-filter: none !important;
  box-shadow: none !important;
}

/* 2. 【核心】美化内层容器 (这里才是真正的胶囊) */
#nonQRFormItems {
  /* --- Chiikawa 缝纫风样式 --- */
  background-color: rgba(255, 247, 248, 1) !important; /* 奶白背景 */
  backdrop-filter: blur(10px);

  /* 边框：吉伊粉色缝纫线 */
  border: 2px dashed var(--chiikawa-pink) !important;
  border-radius: 50px !important; /* 大圆角 */

  /* 阴影：悬浮感 */
  box-shadow: 0 8px 30px rgba(200, 200, 200, 0.4);

  /* 布局 */
  padding: 8px 5px;
  display: flex;
  align-items: center;
  gap: 0px; /* 图标和输入框的间距 */

  /* 动画过渡 */
  transition: all 0.3s cubic-bezier(0.25, 0.8, 0.25, 1);
}

/* 3. 悬停效果：整个胶囊上浮 */
#send_form:hover #nonQRFormItems {
  transform: translateY(-5px);
  background-color: rgba(255, 247, 248, 1) !important; /* 变实心白 */
  border-color: #ffb7b7 !important; /* 缝纫线变深 */
  box-shadow: 0 15px 40px rgba(255, 182, 193, 0.4); /* 粉色光晕 */
}

/* 4. 输入框美化 (蓝色部分) */
#send_textarea {
  /* 必须属性 */
  clip-path: none !important;
  border: none !important; /* 去除原生边框 */

  /* 样式：小八蓝 */
  background-color: rgba(240, 248, 255, 0.6) !important; 
  color: var(--text-grey) !important;

  /* 给输入框单独加一个蓝色细边框，显得精致 */
  border: 2px solid var(--hachiware-blue) !important;
  border-radius: 20px !important;

  padding-left: 10px !important;

  /* 宽度撑满 */
  flex: 1; 
  width: 100%;
}

/* 去除输入时的焦点黑框 */
#send_form:has(#send_textarea:focus-visible) {
  outline: none;
}

/* 5. 悬浮位置控制 */
#form_sheld {
  position: absolute;
  bottom: 5px; /* 距离底部的距离 */
  width: 100%;
  pointer-events: none; /* 两侧留白可穿透点击 */
  z-index: 90;
}

#send_form {
  pointer-events: auto; /* 恢复中间点击 */
  width: 95%; /* 胶囊长度，可以改这里 */
  max-width: 900px;
  margin: 0 auto; /* 居中 */
}

/* 6. 防止遮挡消息 */
.last_mes {
  margin-bottom: 80px !important;
}

/* --- QR按钮美化 (如果你有开启QR) --- */
#qr--bar > .qr--buttons .qr--button {
  border-radius: 1px !important;
  background-color: var(--chiikawa-pink) !important;
  color: var(--text-grey);
  box-shadow: 0 4px 10px rgba(0,0,0,0.1);
}

/* 你的图标样式保持不变 */
#send_form [class*="fa-"] {
    margin: 0 2px;
}

/* --- 图标替换篇 (分别替换) --- */

/* 1. 基础通用设置 */
#send_form [class*="fa-"]::before {
    content: '' !important; /* 隐藏原生图标 */
    display: inline-block;
    vertical-align: middle;
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    transition: transform 0.2s ease;
    /* ✏️ 这里设置所有图标的默认大小 */
    width: 25px;
    height: 25px;    
}

/* 2. 悬停动画：所有图标鼠标放上去都会弹一下 */
#send_form [class*="fa-"]:hover::before {
    transform: scale(1.2);
}

/* =========================================
   ✏️ 请在这里分别填入你的图标链接
   如果不填，它们现在是透明看不到的哦！
   ========================================= */

/* 左侧三道杠菜单 */
#options_button::before {
    background-image: url('https://i.postimg.cc/WbfKF6xM/1766710728524.png');
    width: 30px !important; 
    height: 30px !important; 
}

/* 扩展/魔棒图标 */
#extensionsMenuButton::before {
    background-image: url('https://i.postimg.cc/BQwyLcRD/1766710676270.png');
}

/* 发送按钮 (纸飞机) */
#send_but::before {
    background-image: url('https://i.postimg.cc/L6sw80Cr/1766710779575.png');
}

/* 停止按钮 (正方形/暂停) */
#mes_stop i::before {
    background-image: url('https://i.postimg.cc/qR6RSk2j/556482.gif') !important;
    width: 30px !important; 
    height: 30px !important;
}

/* QR助手 */
#quick-reply-rocket-button i::before {
   background-image: url('https://i.postimg.cc/JhJHPG2g/175908.png') !important; 
}

/* ===== 四、聊天区域 (白玉团子风格 + 背景独立控制版) ===== */

/* --- 1. 聊天主区域背景 --- */
#chat {
  /* 你的聊天背景图 */
  background-image: url('') !important;

  /* 背景设置 */
  background-color: transparent !important; /* 底色透明 */
  background-repeat: repeat; /* 平铺重复 (因为你的图看起来像纹理) */
  /* 如果想全屏拉伸，改成 background-size: cover; */
  background-size: auto; 
  background-attachment: fixed; /* 背景固定，气泡滚动时背景不动 */
  background-position: center;
}

/* --- 2. 侧边栏背景 (抽屉/设置面板) --- */
/* 这里单独控制，以后想换图只改这里 */
.drawer-content, .options-content, #table_drawer_content {
  /* 你的侧边栏背景图 */
  background-image: var(--背景图) !important;

  /* 侧边栏特殊处理：加一层白色蒙版，防止字看不清 */
  background-color: rgba(255, 255, 255, 0.7) !important; /* 90%不透明的白 */
  background-blend-mode: overlay; /* 让背景图透出来的同时变亮 */

  /* 背景设置 */
  background-repeat: repeat;
  background-size: auto;
  background-attachment: fixed;
  background-position: center;

  /* 确保字体颜色适合浅色背景 */
  color: var(--text-grey) !important;
}


/* --- 3. 聊天气泡 (白玉团子风格) --- */
.mes_text {
    /* 形状：精致圆润矩形 */
    border-radius: 18px !important;

    /* 材质：透亮白玉 */
    background-color: rgba(255, 255, 255, 0.92) !important;
    backdrop-filter: blur(2px);

    /* 边框：微弱高光边 */
    border: 2px solid rgba(255, 255, 255, 0.8) !important;

    /* 阴影：空气感投影 + 内部玉石光泽 */
    box-shadow: 
        0 2px 5px rgba(160, 170, 180, 0.05), 
        0 10px 20px rgba(160, 170, 180, 0.05), 
        inset 0 0 10px rgba(255, 255, 255, 0.8);

    color: var(--text-grey) !important;
    /* 上、左：保持正常间距 */
    padding: 20px 15px 50px 15px !important;
    /* 允许贴纸溢出 */
    position: relative;
    overflow: visible !important;
}


/* 用户气泡 (Is User) - 冷白玉 */
.mes[is_user="true"] .mes_text {
    background-color: var(--SmartThemeUserMesBlurTintColor) !important;
    border-color: #f0f8ff !important;
}

/* 角色气泡 (Is Char) - 暖白玉 */
.mes[is_user="false"] .mes_text {
    background-color: var(--SmartThemeBotMesBlurTintColor) !important;
    border-color: #fff0f5 !important;
}

/* --- 4. 气泡贴纸装饰 (请替换乌萨奇素材) --- */

/* ★ 右上角贴纸 */
.mes_text::after {
    content: '';
    display: block;
    position: absolute;

    /* 位置 */
    top: -20px; 
    right: 20px;

    /* 大小 */
    width: 50px; 
    height: 50px;

    /* ✏️ 请填入：趴着的/探头的乌萨奇 */
    background-image: url('https://i.postimg.cc/wT6fk3XX/1766558819301.png'); 
    background-size: contain;
    background-repeat: no-repeat;
    pointer-events: none; 
    z-index: 10;
    filter: drop-shadow(0 2px 2px rgba(0,0,0,0.1));
}

/* ★ 左下角贴纸 */
.mes_text::before {
    content: '';
    display: block;
    position: absolute;

    /* 位置 */
    bottom: -10px;
    left: 20px;

    /* 大小 */
    width: 60px; 
    height: 60px;

    /* ✏️ 请填入：坐着的/小小的吉伊 */
    background-image: url('https://i.postimg.cc/1tVt29DH/5464855.gif');     
    background-size: contain;
    background-repeat: no-repeat;
    pointer-events: none;
    z-index: 2;
    filter: drop-shadow(0 2px 2px rgba(0,0,0,0.1));
}


/* ===== 五、头像框 & 三元素 & 布局 ===== */

/* --- 1. 布局结构调整 --- */
.mes {
    display: flex !important;
    flex-direction: column !important;
    align-items: center !important; 
    gap: 8px; /* 元素间距 */
    padding-bottom: 25px;
}

.mes .mesAvatarWrapper {
    display: flex;
     /* 【核心修改】改为横向排列，但允许换行 */
    flex-direction: row !important; 
    flex-wrap: wrap !important; 
    justify-content: center !important; /* 整体居中 */
    align-items: center !important;
    position: relative; /* 定位基准 */
}

/* --- 2. 头像三明治 (重点！) --- */
.mes .avatar {
    flex-basis: 100% !important;
    position: relative; /* 建立层级基准 */
    width: 80px;  /* 设定一个固定大小，方便对齐贴纸 */
    height: 80px; 
    display: flex;
    justify-content: center;
    align-items: center;
    overflow: visible !important; /* 关键！允许贴纸伸出去 */
    margin-bottom: 10px; /* 给下面的糖果标签留空 */
}

/* ★ 最下层：吉伊和小八举礼物 (背景贴纸) */
.mes .avatar::before {
    content: '';
    display: block;
    position: absolute;

    /* 调整这个贴纸的大小和位置，让它看起来像是在“举”头像 */
    width: 180px; /* 比头像大很多 */
    height: 140px;

    /* 位置微调：往下移，让手正好托住头像 */
    bottom: -15px; 
    left: 49%;
    transform: translateX(-50%); /* 水平居中 */

    /* ✏️ 填入【吉伊和小八举手】的素材链接 */
    background-image: url('https://i.postimg.cc/QCZGfsXz/2233.png'); 
    background-size: contain;
    background-repeat: no-repeat;
    background-position: bottom center;

    z-index: 0; /* 在最底下 */
    pointer-events: none;
}

/* 中间头像 */
.mes .avatar img {
    position: relative;
    z-index: 1; 
    width: 60px;
    height: 60px;
    aspect-ratio: 1 / 1;       
    border-radius: 50% !important; /* 正圆 */
    object-fit: cover; 
    border: 2px solid rgba(255, 255, 255, 1); 
    box-shadow: 0 4px 10px rgba(255, 255, 255, 0.1);
}


/* ★ 最上层：头像框 (装饰) */
.mes .avatar::after {
    content: '';
    display: block;
    position: absolute;

    /* 大小：通常比头像稍微大一圈 */
    top: 0%;
    left: 5%;
    width: 90%;
    height: 90%;

    /* ✏️ 填入【头像框】的素材链接 (中间镂空的PNG) */
    background-image: var(--头像框); 
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;

    z-index: 2; /* 在最顶层 */
    pointer-events: none;
}

/* --- 3. 三元素 (楼层、时间、Token) - 糖果标签修复版 --- */

/* 1. 精准选中这三个小家伙，不管它们在哪里 */
.mes_timer, .tokenCounterDisplay, .mesIDDisplay {
    display: inline-block !important;
    font-size: 12px !important;
    color: #99aab5 !important; 
    font-weight: bold;
    background-color: #ffffff !important; 
    top: 10px;
    padding: 2px 8px !important; 
    border-radius: 50px !important; 
    margin: 2px !important; /* 左右间距 */
    border: 1px dashed var(--chiikawa-pink) !important; 
    box-shadow: 0 2px 5px rgba(0,0,0,0.05) !important;
    white-space: nowrap;
    position: relative;
    z-index: 5;
}
/* 2. (可选) 给它们加个小图标前缀？ */
/* 如果你想让它们更可爱，可以把下面的注释解开 */


.mes_timer::before { content: '🌟 '; }
.tokenCounterDisplay::before { content: '📝 '; }
.mesIDDisplay::before { content: 'Nr.'; }


/* 3. 名字美化 (保持你觉得有效的这部分) */
.mes .name_text {
    /* 稍微调整一下，让它和下面的糖果标签搭配 */
    background: linear-gradient(to right, rgba(255, 253, 246, 1), rgba(255, 251, 218, 1));
    border: 1px solid #fff;
    box-shadow: 0 2px 5px rgba(255, 220, 220, 0.33);
    color: rgba(132, 126, 125, 1) !important;
    border-radius: 12px;
    padding: 4px 12px;
    font-size: 0.95em;
    font-weight: bold;
    margin-bottom: 5px;
    display: inline-block; /* 确保名字也是块状 */
}


/* ===== 六、滚动条 ===== */
::-webkit-scrollbar {
    width: 6px; 
}
::-webkit-scrollbar-track {
    background-color: transparent; 
}
::-webkit-scrollbar-thumb {
    /* 粉蓝渐变滚动条 */
    background-image: linear-gradient(to bottom, #a8d8ea, #fcbad3); 
    border-radius: 10px;
}

/* ===== 聊天内容排版 (原生标签强制美化版) ===== */

/* 1. 普通段落 (p) */
.mes_text p {
    color: var(--SmartThemeBodyColor) !important; /* 使用酒馆设置的主色 */
    margin: 5px 0 10px 0 !important; /* 段落间距 */
    line-height: 1.5 !important; /* 让文字呼吸感强一点 */
}

/* 2. 对话/引用文本 (q - 双引号包裹) */
/* ========================================= */
/* 🏷️ 引用文本美化：樱花粉水平纸条 */
/* ========================================= */

.mes_text q {
  /* --- 布局与形状 --- */
  display: inline-block;          /* 必须：形成纸条块状 */
  padding: 2px 10px;              /* 内边距：左右稍微宽一点，舒适 */
  margin: 3px 2px;                /* 外边距：避免拥挤 */
  border-radius: 6px;             /* 圆润一点的边角，符合粉色系的可爱感 */

  /* --- 颜色与边框 --- */
  background-color: #fffbfd;      /* 🎨 底色：极淡的粉白色，比纯白更柔和 */
  border: 1px solid rgba(238, 136, 163, 0.3); /* 边框：30%透明度的 #EE88A3 */

  /* --- 文字样式 (基于你的原代码) --- */
  color: #EE88A3 !important;      /* 🖋️ 字体颜色：你的核心色 #EE88A3 */
  font-family: inherit !important;/* 继承字体 */
  font-weight: bold !important;   /* 微微加粗 */
  quotes: "“" "”" "‘" "’";        /* 引号样式 */
  text-decoration: none;          /* 去除下划线 */

  /* --- ✨ 核心：端正的粉色立体感 --- */
  transform: translateY(0);       /* 📐 水平摆正 */
  box-shadow: 
      0px 2px 0px rgba(238, 136, 163, 0.25),  /* 下方硬边：模拟纸条厚度 (粉色) */
      0px 3px 6px rgba(238, 136, 163, 0.15);  /* 外层光晕：柔和的粉色投影 */

  /* --- 动画过渡 --- */
  transition: all 0.2s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

/* --- 鼠标悬停交互效果 --- */
.mes_text q:hover {
  transform: translateY(-2px);         /* 悬停时：垂直轻盈上浮 */
  background-color: #ffffff;           /* 变亮为纯白 */
  border-color: rgba(238, 136, 163, 0.6); /* 边框颜色加深 */
  box-shadow: 
      0px 4px 0px rgba(238, 136, 163, 0.3),   /* 厚度感增加 */
      0px 6px 12px rgba(238, 136, 163, 0.25); /* 投影拉长 */
  cursor: default;
}

.mes[is_user="true"] .mes_text q {
    color: rgba(94, 175, 209, 1) !important; /* 你的引用色变量 */
    font-family: inherit !important; /* 继承圆体 */
    font-weight: bold !important; /* 微微加粗，强调对话感 */
    quotes: "“" "”" "‘" "’"; /* 修正引号样式 */
}

/* 3. 心理/旁白 (em - 星号包裹) - 建议搭配小八蓝背景 */
.mes_text em {
    color: var(--SmartThemeEmColor) !important; /* 你的斜体色变量 */
    font-style: normal !important; /* 很多字体斜体很难看，强制扶正 */

    /* 增加一个淡淡的蓝色荧光笔背景，像是在划重点 */
    background-color: rgba(230, 240, 255, 0.6) !important; 
    padding: 0 4px !important;
    border-radius: 4px !important;
}

/* 4. 强调/加粗 (strong - 双星号) - 吉伊粉 */
.mes_text strong {
    color: rgba(209, 94, 94, 1) !important; /* 用粉色 */
    /* 如果变量没生效，回退到 #db8a8a */
    font-weight: 900 !important;
    background: rgba(255, 255, 255, 1) !important;
}

/* 5. 荧光笔引用块 (blockquote - > 开头) - 黄色便利贴 */
.mes_text blockquote {
    background-color: #fffdf2 !important; /* 淡黄底 */
    border-left: 4px solid #f0e68c !important; /* 黄边 */
    border-radius: 8px !important;
    margin: 10px 0 !important;
    padding: 10px 15px !important;
    color: #8a8a6d !important; /* 墨绿字 */
    box-shadow: 2px 2px 5px rgba(0,0,0,0.05) !important;
}
/* 强制把引用块里面的 p 颜色改掉，不然会跟主色一样 */
.mes_text blockquote p {
    color: #8a8a6d !important; 
    margin: 0 !important;
}

/* 6. 单行代码 (code) - 粉色标签 */
.mes_text :not(pre) > code {
    background-color: #fff0f5 !important; /* 薰衣草腮红 */
    color: #d15e5e !important; /* 深红字 */
    border: 1px dashed #ffc0cb !important;
    border-radius: 6px !important;
    padding: 2px 6px !important;
    font-family: inherit !important; /* 不用等宽字体，保持可爱 */
}

/* 7. 代码块 (乌萨奇 / YAHOO! 黄色能量版) */
.mes_text pre {
    /* 1. 背景：极淡的奶黄包色，护眼又温暖 */
    background-color: #fffdf5 !important; 

    /* 2. 文字：焦糖布丁色 (深褐黄) */
    /* 这样对比度高，字看得清，而且像巧克力酱 */
    color: #78350f !important; 

    /* 3. 边框：乌萨奇本体的高饱和黄色 */
    /* 用 dashed 虚线，体现乌萨奇那种疯疯癫癫的活力感 */
    border: 3px dashed #facc15 !important; 
    border-radius: 15px !important; /* 圆润一点 */

    /* 4. 排版细节 */
    padding: 15px !important;
    margin: 15px 0 !important;
    font-family: Consolas, monospace !important;
    font-size: 0.9em !important;
    line-height: 1.5 !important;
    white-space: pre-wrap !important;

    /* 5. 阴影：淡淡的黄色光晕 */
    box-shadow: 4px 4px 0px rgba(250, 204, 21, 0.2) !important;
}

/* 强行覆盖里面原本乱七八糟的高亮色 */
.mes_text pre code {
    background: transparent !important;
    border: none !important;
    /* 继承上面的焦糖色，保证看起来整洁 */
    color: inherit !important; 
    text-shadow: none !important;
}

/* (可选) 给乌萨奇的代码块加个小耳朵装饰？ */
/* 如果想要更可爱，可以解开下面的注释 */

.mes_text pre::before {
    content: '🐰 YAHA!!';
    display: block;
    font-weight: bold;
    color: #facc15;
    margin-bottom: 5px;
    font-size: 0.8em;
}


/* 8. 分割线 (hr) - 爱心剪刀线 */
.mes_text hr {
    border: none !important;
    border-top: 2px dashed #ffb7c5 !important; /* 粉色虚线 */
    margin: 20px 0 !important;
    position: relative !important;
    overflow: visible !important;
    opacity: 1 !important;
}
/* 中间的小爱心 */
.mes_text hr::after {
    content: '❤' !important;
    position: absolute !important;
    left: 50% !important;
    top: -12px !important; /* 往上提一点，压在线上 */
    transform: translateX(-50%) !important;
    background-color: #fff !important; /* 背景遮挡线条 */
    padding: 0 8px !important;
    color: #ffb7c5 !important;
    font-size: 14px !important;
}


/* ===== 七、输入框提示文字 (适配悬浮版) ===== */
/* 必须配合悬浮栏的层级进行调整 */
#nonQRFormItems {
    position: relative;
    z-index: 100;
}
#send_textarea::placeholder {
    color: transparent !important;
}

#nonQRFormItems:has(#send_textarea:placeholder-shown)::before {
    content: var(--自定义输入框文字);
    color: #aab; /* 稍微深一点的灰蓝色，防止看不清 */
    position: absolute; 
    left: 55%;
    top: 50%;
    transform: translate(-50%, -50%); 
    font-size: 0.55em;  
    pointer-events: none; 
    white-space: nowrap;
    z-index: 10; /* 确保在最上层 */
    opacity: 0.8;
}

/* ===== 八、正则+脚本易读优化 ===== */
.regex-script-label.flex-container,
.flex-container .script-item {
  background: #fff;
  border: 1px solid #eee;
  border-radius: 12px;
  box-shadow: 0 2px 5px rgba(0,0,0,0.02);
}
.regex_script_name, .script-item-name {
    color: var(--text-grey);
}
/* 防误触 */
#saved_regex_scripts,
#saved_scoped_scripts,
#saved_preset_scripts,
#global-script-list,
#character-script-list {
  margin-right: 30px !important;
}

/* ===== “加载更多消息”美化 ===== */
#show_more_messages {
  font-size: 0 !important;
  color: transparent !important; 
  display: block;
  padding: 8px 30px;
  margin: 15px auto; 
  width: fit-content; 
  background-color: #fff; 
  border: 2px dashed var(--chiikawa-pink); /* 粉色虚线边框 */
  border-radius: 50px; /* 胶囊形状 */
  cursor: pointer;
  transition: all 0.3s ease;
}

#show_more_messages::before {
  content: var(--自定义“加载更多信息”文案); 
  font-size: 14px !important; 
  color: var(--text-grey) !important; 
}

#show_more_messages:hover {
  background-color: var(--chiikawa-pink);
  border-style: solid; /* 悬停变实线 */
}
#show_more_messages:hover::before {
  color: #fff !important; 
}

/* ===== 九、思维链美化 ===== */
/* 设计成一个像是“便利贴”的感觉 */
.mes_reasoning_header {
  background-color: var(--usagi-yellow); /* 奶黄色便利贴 */
  border: 1px solid #f0e68c; 
  border-radius: 10px 10px 0 0; 
  padding: 5px 15px; 
}

.mes_reasoning_header_title {
  font-size: 0 !important;
}
.mes_reasoning_header_title::before {
  content: var(--自定义思维链文案);
  font-size: 13px;
  color: #8a8a5c; 
}

.mes_reasoning {
  background-color: #fffdf5; /* 极淡的黄色背景 */
  border: 1px solid #f0e68c;
  border-top: none;
  border-radius: 0 0 10px 10px;
  color: #8a8a5c;
  font-family: monospace;
}



/* ===== 十、收藏栏左右滑动 ===== */
.hotswap.avatars_inline {
  display: flex;
  flex-wrap: nowrap;
  overflow-x: auto;
  padding: 0px 15px;
  gap: 5px;
}

/* 强制消除最后一条消息头像下方的“幽灵留白” */
.mes.last_mes .mesAvatarWrapper {
  padding-bottom: 0px !important; /* 酒馆默认是35px，我们要归零 */
  margin-bottom: 0px !important;  /* 确保外边距也老实 */
}


/* ===== 十一、BUG修复补丁：拯救删除按钮 ===== */

/* 1. 核心修复：提升删除确认框的层级 */
/* 只要比底栏的 z-index: 90 大就可以，这里设为 100 保险 */
#dialogue_del_mes {
    position: relative !important; 
    z-index: 100 !important; 

}

/* 2. 确保按钮本身可以响应点击 */
#dialogue_del_mes .menu_button {
    pointer-events: auto !important;
    cursor: pointer !important;
    z-index: 101 !important;
}

/* ===== 十二、气泡按钮美化 (感谢 Nini老师提供的修改小铅笔代码 - 图片模式) ===== */

/* --- 1. 定位调整 (你想移动位置就在这里改) --- */
.mes_buttons {
    /* 这里的数值可以自己调 */
    top: -40px !important;    /* 负数往上跑 */
    right: 23px !important;   /* 距离右边的距离 */

    gap: 2px !important;      /* 两个按钮之间的间距 */

}


/* --- 2. 隐藏原图标 --- */
.mes_edit > i,
.extraMesButtonsHint > i {
    display: none !important;
}


/* --- 3. 基础样式清除 (防止有灰底或阴影) --- */
.mes_edit,
.extraMesButtonsHint {
    background: none !important;
    width: auto !important;
    height: auto !important;
    box-shadow: none !important;
    text-shadow: none !important;
    border: none !important;
    padding: 0 !important;

    /* 鼠标变成小手 */
    cursor: pointer;
    /* 增加过渡动画，动起来丝滑 */
    transition: transform 0.2s ease;
}


/* --- 4. 核心：定义新图标的通用样子 --- */
.mes_edit::before,
.extraMesButtonsHint::before {
    content: '' !important;  /* 必须留空，因为我们要放图 */
    display: block !important;

    /* ✏️ 在这里控制图标大小 */
    width: 20px;   
    height: 20px;

    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
}


/* --- 5. 填入素材 (这里换成你的图片链接) --- */

/* 编辑/铅笔按钮 */
.mes_edit::before {
    /* 👇 你的铅笔贴纸链接 */
    background-image: url('https://i.postimg.cc/fLNWKGBT/1766584042544.png'); 
}

/* 菜单/三点按钮 */
.extraMesButtonsHint::before {
    /* 👇 你的三个点贴纸链接 */
    background-image: url('https://i.postimg.cc/9QgsJf7v/180343.png'); 
}


/* --- 6. 悬停交互 (动效) --- */
/* 鼠标放上去稍微放大一点点，像 Nini 代码里那样 */
.mes_edit:hover,
.extraMesButtonsHint:hover {
    transform: scale(1.2); /* 1.15 或者 1.2 都可以 */
    filter: drop-shadow(0 2px 3px rgba(0,0,0,0.1)); /* 加一点立体感 */
}

/* ===== 十三、防遮挡补丁 (让头部按钮完整显示) ===== */

/* 1. 【核心】解除封印：允许内容溢出 */
/* 告诉消息气泡和容器：不要切掉跑出去的贴纸！ */
.mes, 
.mes_text,
.mes_block {
    overflow: visible !important;
    clip-path: none !important; /* 有些主题会用这个裁剪，强制关掉 */
}

/* 2. 【核心】增加间距：给头顶腾位置 */
/* 既然按钮往上跑了，我们需要把每条消息之间的距离拉大一点，
   不然按钮会撞到上一条消息的屁股 */
.mes {
    margin-top: 10px !important; /* 原来可能是20px，加大力度 */
    padding-top: 10px !important; 
}

/* 3. 【核心】层级提升：谁也别想压住我 */
/* 确保按钮浮在所有气泡和背景的上面 */
.mes_buttons {
    z-index: 99 !important; 
}


/* ==================== 侧边栏美化 (棉花糖·特调版) ==================== （全部来自Nakari老师的代码，感谢）*/

/* --- 1. 图标样式 (奶呼呼的粉色) --- */
.fa, .fa-brands, .fa-classic, .fa-regular, .fa-sharp, .fa-solid:not(.fav_on, .world_set, .fa-power-off), .fab, .far, .fas {
    color: var(--chiikawa-pink2) !important; 
    font-size: 15px !important;
    text-shadow: none !important; 
    filter: none !important;
    opacity: 0.8 !important;
}


/* --- 2. 标题栏样式 (保留你的蓝色贴纸) --- */
.inline-drawer-header, 
#extensions_settings .inline-drawer-toggle.inline-drawer-header, 
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header, 
.standoutHeader,
h4 {
    background-image: url('https://i.postimg.cc/6QZHWKYv/1766737614669.jpg') !important;
    background-size: cover !important;
    background-position: center !important;
    background-repeat: no-repeat !important;
    border: 2px solid var(--hachiware-blue) !important; 
    border-radius: 12px !important;

    /* 文字颜色：虽然背景是蓝的，但我们要深色字吗？
       通常深色背景配白字，但如果你坚持要深色字：*/
    color: var(--choco-text) !important; /* 标题还是白色好看，不然在蓝图上看不清，如果不喜欢请改 var(--choco-text) */
    text-shadow: 0 1px 2px rgba(100, 100, 100, 0.5) !important; /* 稍微加点阴影防止撞色看不清 */

    padding: 6px 10px !important;
    box-shadow: none !important;
}

/* --- 3. 抽屉页下拉箭头 (干净的箭头) --- */
.inline-drawer-icon {
    -webkit-appearance: none;
    appearance: none;
    width: 25px;
    height: 25px;
    background-image: url('https://i.postimg.cc/5NPYntcM/1766583033161.png');
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    cursor: pointer;
    background-color: transparent !important; /* 确保无底色 */
}
/* 隐藏字符 */
.inline-drawer-icon::before { display: none !important; }


/* --- 4. 滑动条 （小八蓝 -> 吉伊粉 渐变) --- */
input[type="range"] {
    /* 🍦 像融化的冰淇淋一样的渐变轨道 */
    background: linear-gradient(to right, var(--hachiware-blue), var(--chiikawa-pink)) !important; 
    height: 8px !important; /* 稍微厚一点点，显得圆润 */
    border-radius: 10px;
    box-shadow: none !important;
    border: none !important;
}

/* 滑块 (去黑圈) */
input[type="range"]::-webkit-slider-thumb {
    -webkit-appearance: none;
    appearance: none;
    width: 28px;
    height: 28px;
    background-color: transparent !important;
    background-image: url('https://i.postimg.cc/rmkyJBQp/1766583748204.png');
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;

    /* ⚡️ 强力去黑圈 */
    box-shadow: none !important; 
    border: none !important;     
    outline: none !important;    
    margin-top: 0px; 
}


/* --- 5. 输入框和下拉框 (白底 + 粉色软糯边框 + 焦糖色文字) --- */
input:not(input[type="range"], input[type='checkbox']), 
select, 
.text_pole,
textarea {
    background-color: rgba(255, 255, 255, 1) !important; /* 纯白底，干净 */

    /* 🍬 重点：边框变成了吉伊粉！ */
    border: 2px solid var(--chiikawa-pink) !important; 

    /* 🍫 重点：文字变成了焦糖可可色，深色超清晰！ */
    color: var(--choco-text) !important; 

    border-radius: 12px !important; /* 圆角加大，更软 */
    padding: 5px 10px !important;

    /* ⚡️ 强力去阴影 */
    box-shadow: none !important;
    filter: none !important;
    outline: none !important;
}


/* --- 6. 勾选框 (粉色方糖风格) --- */
input[type="checkbox"] {
    appearance: none;
    -webkit-appearance: none;
    width: 18px;
    height: 18px;
    background-color: #ffffff;

    /* 粉色边框 */
    border: 2px solid var(--usagi-pink) !important; 
    border-radius: 6px;

    display: inline-block;
    position: relative;
    vertical-align: middle;
    box-shadow: none !important;
    outline: none !important;
}

/* 勾选后的状态 - 变成粉色实心 */
input[type="checkbox"]:checked {
    background-color: var(--chiikawa-pink2) !important;
    border-color: var(--usagi-pink) !important;
}

/* 勾选后的对号 */
input[type="checkbox"]:checked::before {
    content: '✔';
    display: block;
    color: white; /* 粉底白字，很嫩 */
    font-size: 14px;
    line-height: 16px; 
    text-align: center;
    width: 100%;
    height: 100%;
    box-shadow: none !important;
}

/* ==================== 侧边栏美化结束 ==================== */

